302: const wildcard = "*"
303: 
304: func appendIfNotEmpty(s []string, v ...string) []string {
305: 	for _, vs := range v {
306: 		if vs != "" {
307: 			s = append(s, vs)
308: 		}
309: 	}
310: 
311: 	return s
312: }
