441: func experimentalFieldSkipHookFunc(types ...reflect.Type) mapstructure.DecodeHookFunc {
442: 	return func(
443: 		f reflect.Type,
444: 		t reflect.Type,
445: 		data interface{}) (interface{}, error) {
446: 		if len(types) == 0 {
447: 			return data, nil
448: 		}
449: 
450: 		if t.Kind() != reflect.Struct {
451: 			return data, nil
452: 		}
453: 
454: 		// skip any types that match a type in the provided set
455: 		for _, typ := range types {
456: 			if t == typ {
457: 				return reflect.New(typ).Interface(), nil
458: 			}
459: 		}
460: 
461: 		return data, nil
462: 	}
463: }
