465: // stringToSliceHookFunc returns a DecodeHookFunc that converts
466: // string to []string by splitting using strings.Fields().
467: func stringToSliceHookFunc() mapstructure.DecodeHookFunc {
468: 	return func(
469: 		f reflect.Kind,
470: 		t reflect.Kind,
471: 		data interface{}) (interface{}, error) {
472: 		if f != reflect.String || t != reflect.Slice {
473: 			return data, nil
474: 		}
475: 
476: 		raw := data.(string)
477: 		if raw == "" {
478: 			return []string{}, nil
479: 		}
480: 
481: 		return strings.Fields(raw), nil
482: 	}
483: }
