func GetExporter(ctx context.Context, cfg *config.MetricsConfig) (reader sdkmetric.Reader, shutdown func(context.Context) error, err error) {
	metricExpOnce.Do(func() {
		var (
			exp sdkmetric.Reader
			fn  func(context.Context) error
		)

		switch cfg.Exporter {
		case config.MetricsPrometheus:
			// exporter registers itself on the prom client DefaultRegistrar
			promExporter, promErr := prometheus.New()
			if promErr != nil {
				err = promErr
				return
			}

			exp = promExporter
			fn = promExporter.Shutdown
		case config.MetricsOTLP:
			u, parseErr := url.Parse(cfg.OTLP.Endpoint)
			if parseErr != nil {
				err = fmt.Errorf("parsing otlp endpoint: %w", parseErr)
				return
			}

