import (
	"context"
	"sync"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"go.flipt.io/flipt/internal/config"
)

func TestGetExporter(t *testing.T) {
	tests := []struct {
		name    string
		cfg     *config.MetricsConfig
		wantErr string
	}{
		{
			name: "otlp http",
			cfg: &config.MetricsConfig{
				Enabled:  true,
				Exporter: config.MetricsOTLP,
				OTLP: config.OTLPMetricsConfig{
					Endpoint: "http://localhost:4318",
					Headers: map[string]string{
						"hello": "world",
					},
				},
			},
		},
		{
			name: "otlp https",
			cfg: &config.MetricsConfig{
				Enabled:  true,
				Exporter: config.MetricsOTLP,
				OTLP: config.OTLPMetricsConfig{
					Endpoint: "https://localhost:4318",
					Headers: map[string]string{
						"hello": "world",
					},
				},
			},
		},
		{
			name: "otlp grpc",
			cfg: &config.MetricsConfig{
				Enabled:  true,
				Exporter: config.MetricsOTLP,
				OTLP: config.OTLPMetricsConfig{
					Endpoint: "grpc://localhost:4317",
					Headers: map[string]string{
						"hello": "world",
					},
				},
			},
		},
		{
			name: "otlp no scheme",
			cfg: &config.MetricsConfig{
				Enabled:  true,
				Exporter: config.MetricsOTLP,
				OTLP: config.OTLPMetricsConfig{
					Endpoint: "localhost:4317",
					Headers: map[string]string{
						"hello": "world",
					},
				},
			},
		},
		{
			name:    "unsupported exporter",
			cfg:     &config.MetricsConfig{},
			wantErr: "unsupported metrics exporter: ",
		},
		{
			name: "prometheus",
			cfg: &config.MetricsConfig{
				Enabled:  true,
				Exporter: config.MetricsPrometheus,
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			// reset the once so each case performs a fresh initialization
			metricExpOnce = sync.Once{}

			exp, expFunc, err := GetExporter(context.Background(), tt.cfg)
			if tt.wantErr != "" {
				assert.EqualError(t, err, tt.wantErr)
				return
			}

			require.NoError(t, err)
			assert.NotNil(t, exp)
			assert.NotNil(t, expFunc)

			if expFunc != nil {
				assert.NoError(t, expFunc(context.Background()))
			}
		})
	}
}
